'AC-testing.benchmarks.15'; from __future__ import annotations; import json; from pathlib import Path; from typing import Any; import pytest; from common.testing.benchmarks import generate_benchmark_index as generator; _summary = lambda version, run_at, status='PASS', **extra: {'version': version, 'run_at': run_at, 'status': status, 'cases_total': 7, 'cases_passed': 7 if status == 'PASS' else 3, 'duration_seconds': 12.5, 'max_equation_delta': '0.00', **extra}
def _publish(directory: Path, summary: dict[str, Any]) -> None: folder = directory / summary['version']; folder.mkdir(parents=True, exist_ok=True); (folder / 'summary.json').write_text(json.dumps(summary), encoding='utf-8')
_manifest = lambda directory: json.loads((directory / 'manifest.json').read_text(encoding='utf-8'))
def test_AC_testing_benchmarks_15_the_index_lists_the_published_runs_and_the_current_run(tmp_path: Path) -> None: current, history = (tmp_path / 'docs', tmp_path / 'published'); _publish(history, _summary('v0.2.2', '2026-10-15T08:30:00+00:00', 'FAIL')); _publish(history, _summary('v0.2.3', '2026-10-15T10:19:00+00:00')); _publish(current, _summary('v0.2.6', '2026-10-19T09:12:00+00:00')); assert generator.main(['--benchmarks-dir', str(current), '--history-dir', str(history)]) == 0; manifest = _manifest(current); assert [(run['version'], run['status']) for run in manifest] == [('v0.2.6', 'PASS'), ('v0.2.3', 'PASS'), ('v0.2.2', 'FAIL')]; index = (current / 'index.html').read_text(encoding='utf-8'); assert all((version in index for version in ('v0.2.2', 'v0.2.3', 'v0.2.6'))); _m1_tmp = tmp_path / '_m1'; _m1_tmp.mkdir(exist_ok=True); _m1_current, _m1_history = (_m1_tmp / 'docs', _m1_tmp / 'published'); _publish(_m1_history, _summary('v0.2.6', '2026-10-19T07:09:00+00:00', 'FAIL')); _publish(_m1_history, _summary('v0.2.3', '2026-10-15T10:19:00+00:00')); _publish(_m1_current, _summary('v0.2.6', '2026-10-19T09:12:00+00:00', 'PASS')); generator.main(['--benchmarks-dir', str(_m1_current), '--history-dir', str(_m1_history)]); assert [(_m1_run['version'], _m1_run['status'], _m1_run['run_at']) for _m1_run in _manifest(_m1_current)] == [('v0.2.6', 'PASS', '2026-10-19T09:12:00+00:00'), ('v0.2.3', 'PASS', '2026-10-15T10:19:00+00:00')]; _m2_tmp = tmp_path / '_m2'; _m2_tmp.mkdir(exist_ok=True); _m2_current = _m2_tmp / 'docs'; _publish(_m2_current, _summary('v0.2.6', '2026-10-19T09:12:00+00:00')); assert generator.main(['--benchmarks-dir', str(_m2_current), '--history-dir', str(_m2_tmp / 'absent')]) == 0; assert [_m2_run['version'] for _m2_run in _manifest(_m2_current)] == ['v0.2.6']; _m3_tmp = tmp_path / '_m3'; _m3_tmp.mkdir(exist_ok=True); _m3_current = _m3_tmp / 'docs'; _publish(_m3_current, _summary('v0.2.6', '2026-10-19T09:12:00+00:00')); generator.main(['--benchmarks-dir', str(_m3_current)]); assert [_m3_run['version'] for _m3_run in _manifest(_m3_current)] == ['v0.2.6']
def test_AC_testing_benchmarks_15_a_history_file_that_is_no_summary_is_skipped_with_a_warning(tmp_path: Path, capsys: pytest.CaptureFixture[str]) -> None: current, history = (tmp_path / 'docs', tmp_path / 'published'); _publish(history, _summary('v0.2.3', '2026-10-15T10:19:00+00:00')); (history / 'v0.2.4').mkdir(); (history / 'v0.2.4' / 'summary.json').write_text('{not json', encoding='utf-8'); (history / 'v0.2.5').mkdir(); (history / 'v0.2.5' / 'summary.json').write_text('[1, 2]', encoding='utf-8'); _publish(current, _summary('v0.2.6', '2026-10-19T09:12:00+00:00')); assert generator.main(['--benchmarks-dir', str(current), '--history-dir', str(history)]) == 0; assert [run['version'] for run in _manifest(current)] == ['v0.2.6', 'v0.2.3']; err = capsys.readouterr().err; assert 'Failed to parse' in err and 'v0.2.4' in err; assert 'not a JSON object' in err and 'v0.2.5' in err
